    // Helper: check if a kingdom has a specific special law
    function hasSpecialLaw(kingdom, lawId) {
        if (!kingdom || !kingdom.laws || !kingdom.laws.specialLaws) return false;
        return kingdom.laws.specialLaws.some(l => l.id === lawId);
    }

    // Helper: check if it's nighttime (between 20:00 and 5:00)
    function isNightTime() {
        const w = Engine.getWorld ? Engine.getWorld() : null;
        const hour = w ? (w.hour || 0) : 12;
        return hour >= 20 || hour < 5;
    }

