    function getPlayerWorldPosition() {
        if (!player.traveling) {
            if (player.worldX != null && player.worldY != null) return { x: player.worldX, y: player.worldY };
            var town = Engine.findTown(player.townId);
            return town ? { x: town.x, y: town.y } : null;
        }

        // Interpolate from waypoints (free travel)
        if (player.travelWaypoints && player.travelWaypoints.length >= 2) {
            var progress = player.travelProgress || 0;
            var wps = player.travelWaypoints;
            var totalDist = 0;
            var segDists = [];
            for (var i = 1; i < wps.length; i++) {
                var d = Math.hypot(wps[i].x - wps[i-1].x, wps[i].y - wps[i-1].y);
                segDists.push(d);
                totalDist += d;
            }
            var targetDist = progress * totalDist;
            var acc = 0;
            for (var j = 0; j < segDists.length; j++) {
                if (acc + segDists[j] >= targetDist) {
                    var t = (targetDist - acc) / segDists[j];
                    return {
                        x: wps[j].x + (wps[j+1].x - wps[j].x) * t,
                        y: wps[j].y + (wps[j+1].y - wps[j].y) * t
                    };
                }
                acc += segDists[j];
            }
            return wps[wps.length - 1];
        }

        // Fallback: interpolate from town route
        if (player.travelRoute && player.travelRoute.length > 0) {
            var origin = Engine.findTown(player.travelOrigin || player.townId);
            var dest = Engine.findTown(player.travelDestination);
            if (origin && dest) {
                var p = player.travelProgress || 0;
                return { x: origin.x + (dest.x - origin.x) * p, y: origin.y + (dest.y - origin.y) * p };
            }
        }

        return null;
    }

    function cleanupTravelState() {
        // Release off-sea ship assignment if any
        if (player.offSeaShipId && player.ships) {
            var offSeaShip = player.ships.find(function(s) { return s.id === player.offSeaShipId; });
            if (offSeaShip) offSeaShip.assignedOffSea = false;
        }
        player.travelDestination = null;
        player.travelDestCoords = null;
        player.travelWaypoints = null;
        player.travelRoute = null;
        player.travelTotalDist = 0;
        player.travelBySea = false;
        player.travelOffroad = false;
        player.travelOffSea = false;
        player.offSeaShipId = null;
        player._offSeaPirateChance = 0;
        player.travelPaid = false;
        player.travelMode = null;
        player.travelSeaMode = null;
        player._campPromptNeeded = false;
        player.travelRestBonus = false;
        player.travelOrigin = null;
        player.travelCompanions = [];
    }

    // Move all personal guards to the player's current town
