            var _gp = g.personId ? Engine.findPerson(g.personId) : null;
            if (_gp && !_gp.alive) {
                Engine.logEvent('⚔️ Guard ' + (g.name || 'Unknown') + ' has died and been dismissed.');
                return false;
            }
