                var _pRes2 = findResource(resourceId);
                var _pResW2 = _pRes2 ? (_pRes2.weight || 1) : 1;
                var _pSpace2 = Math.max(0, Math.floor((_pCap2 - _pOutputUsed2) / _pResW2));
