    function proposeKingAction(kingdomId, actionId, subChoice) {
        if (!player.royalAdvisorBenefits || !player.royalAdvisorBenefits.swayOverKing) return { success: false, message: 'Not a royal advisor.' };
        if (kingdomId !== player.royalAdvisorKingdomId) return { success: false, message: 'No sway in this kingdom.' };
        if (player.politicalCapital <= 0) return { success: false, message: 'No political capital remaining.' };

        // Regen check
        if (Engine.getDay() - player.politicalCapitalResetDay >= CONFIG.ADVISE_KING_CAPITAL_REGEN_DAYS) {
            var maxCap = CONFIG.ADVISE_KING_POLITICAL_CAPITAL_MAX;
            var houses = player.houses || [];
            for (var hi = 0; hi < houses.length; hi++) {
                var hType = CONFIG.HOUSING_TYPES.find(function(h) { return h.id === houses[hi].type; });
                if (hType && hType.politicalInfluence) maxCap += hType.politicalInfluence;
            }
            player.politicalCapital = maxCap;
            player.politicalCapitalResetDay = Engine.getDay();
        }

        var actions = getProposableActions(kingdomId);
        var action = null;
        for (var i = 0; i < actions.length; i++) {
            if (actions[i].id === actionId) { action = actions[i]; break; }
        }
        if (!action) return { success: false, message: 'Action not available.' };

        player.politicalCapital--;

        var rng = Engine.getRng();
        var accepted = rng && rng.chance(action.finalChance);

        if (!accepted) {
            var kingdom = Engine.findKingdom(kingdomId);
            var kingName = 'The King';
            try { var kp = Engine.findPerson(kingdom.king); kingName = kp ? kp.firstName : 'The King'; } catch(e) {}
            // Failed proposal: -2 king relationship, -0.5 kingdom rep
            modifyRelationship(kingdom.king, -2);
            modifyKingdomReputation(kingdomId, -0.5);
            Engine.logEvent('❌ ' + kingName + ' rejected the Royal Advisor\'s proposal: ' + action.name);
            return { success: false, message: kingName + ' rejected your proposal: ' + action.name + '. (-1 political capital, -2 king relationship)', chance: Math.round(action.finalChance * 100) };
        }

        // Execute the action
        if (typeof action.execute === 'function') action.execute(subChoice);

        autoJournalCapture('politics', 'I proposed ' + action.name + ' to the king, and it was accepted! My influence at court grows.', { mood: 'confident' });
        return { success: true, message: 'The king accepted: ' + action.name + '! (-1 political capital)', chance: Math.round(action.finalChance * 100) };
    }

    // ========================================================
    // §11.5B ROYAL ADVISOR CONSULTATION RESPONSES
    // ========================================================
    function getPendingKingDecisions() {
        var kId = player.royalAdvisorKingdomId || player.citizenshipKingdomId;
        if (!kId) return [];
        if (typeof Engine !== 'undefined' && Engine.getPendingKingDecisions) {
            return Engine.getPendingKingDecisions(kId);
        }
        return [];
    }

    function respondToKingDecision(decisionId, response) {
        var kId = player.royalAdvisorKingdomId || player.citizenshipKingdomId;
        if (!kId) return { success: false, message: 'Not associated with any kingdom.' };
        if ((player.socialRank[kId] || 0) < 6) return { success: false, message: 'Only Royal Advisors can respond to king consultations.' };
        if (typeof Engine !== 'undefined' && Engine.respondToKingDecision) {
            var result = Engine.respondToKingDecision(kId, decisionId, response);
            if (result.success) {
                autoJournalCapture('politics', response === 'agree'
                    ? 'I supported the king\'s decision. Our alliance remains strong.'
                    : (result.swayed
                        ? 'I counseled the king against his plan, and he listened. My influence at court grows.'
                        : 'I opposed the king\'s plan, but he overruled me. A reminder that even advisors have limits.'),
                    { mood: result.swayed ? 'confident' : (response === 'agree' ? 'content' : 'frustrated') });
            }
            return result;
        }
        return { success: false, message: 'Engine not available.' };
    }

    // ========================================================
    // §11.5B2 DIRECTED KING COMMISSIONS (Player-side)
    // ========================================================

    function checkKingCommissions() {
        if (!player.socialRank) return;
        var kingdoms = [];
        try { kingdoms = Engine.getKingdoms ? Engine.getKingdoms() : []; } catch(e) {}

        for (var ki = 0; ki < kingdoms.length; ki++) {
            var k = kingdoms[ki];
            var rank = player.socialRank[k.id] || 0;
            if (rank < 4) continue;

            // Check for deadline failures
            if (typeof Engine.checkDirectedCommissionDeadline === 'function') {
                var deadlineResult = Engine.checkDirectedCommissionDeadline(k.id);
                if (deadlineResult && deadlineResult.expired) {
                    player.reputation[k.id] = Math.max(0, (player.reputation[k.id] || 50) - deadlineResult.repLoss);
                    if (typeof UI !== 'undefined' && UI.toast) UI.toast('⏳ You ignored the king\'s commission! (-' + deadlineResult.repLoss + ' reputation)', 'danger');
                }
                if (deadlineResult && deadlineResult.failed) {
                    player.reputation[k.id] = Math.max(0, (player.reputation[k.id] || 50) - deadlineResult.repLoss);
                    if (deadlineResult.demotionTriggered) {
                        // Lord demotion for failing mandatory commission
                        player.socialRank[k.id] = 4; // demote to Minor Noble
                        player.reputation[k.id] = Math.min(player.reputation[k.id] || 50, 60);
                        if (typeof UI !== 'undefined' && UI.toast) UI.toast('❌ You failed the king\'s commission! Demoted to Minor Noble!', 'danger');
                        autoJournalCapture('politics', 'I failed the king\'s commission. My lordship has been revoked.', { mood: 'devastated' });
                    } else {
                        if (typeof UI !== 'undefined' && UI.toast) UI.toast('❌ Commission deadline passed! (-' + deadlineResult.repLoss + ' reputation)', 'warning');
                    }
                }
            }

            // Check for new commission notification
            var comm = null;
            try { comm = Engine.getDirectedPlayerCommission(k.id); } catch(e) {}
            player._lastCommNotified = player._lastCommNotified || {};
            if (comm && comm.status === 'pending' && !player._lastCommNotified[k.id]) {
                player._lastCommNotified[k.id] = comm.id;
                if (typeof UI !== 'undefined' && UI.toast) {
                    UI.toast('👑 The King of ' + k.name + ' has a personal commission for you!', 'info', 'commission');
                }
                autoJournalCapture('politics', 'The king of ' + k.name + ' has personally tasked me with: ' + comm.description, { mood: 'dutiful' });
            } else if (!comm || comm.status !== 'pending') {
                if (player._lastCommNotified && player._lastCommNotified[k.id]) delete player._lastCommNotified[k.id];
            }
        }
    }

    function acceptKingCommission(kingdomId) {
        if (!kingdomId) kingdomId = player.citizenshipKingdomId;
        if (!kingdomId) return { success: false, message: 'No kingdom specified.' };
        var result = Engine.respondToDirectedCommission(kingdomId, true);
        if (result && result.success) {
            autoJournalCapture('politics', 'I have accepted the king\'s commission. Time to deliver.', { mood: 'determined' });
            if (typeof UI !== 'undefined' && UI.toast) UI.toast('✅ Commission accepted!', 'success');
        }
        return result;
    }

    function refuseKingCommission(kingdomId) {
        if (!kingdomId) kingdomId = player.citizenshipKingdomId;
        if (!kingdomId) return { success: false, message: 'No kingdom specified.' };
        var result = Engine.respondToDirectedCommission(kingdomId, false);
        if (result && result.success) {
            player.reputation[kingdomId] = Math.max(0, (player.reputation[kingdomId] || 50) - result.repLoss);
            if (result.demotionTriggered) {
                // Lord refused mandatory commission — immediate demotion
                player.socialRank[kingdomId] = 4; // Minor Noble
                player.reputation[kingdomId] = Math.min(player.reputation[kingdomId] || 50, 60);
                autoJournalCapture('politics', 'I refused the king\'s commission as a Lord. I have been stripped of my lordship.', { mood: 'devastated' });
                if (typeof UI !== 'undefined' && UI.toast) UI.toast('❌ You refused a mandatory commission! Demoted to Minor Noble! (-20 rep)', 'danger');
            } else {
                autoJournalCapture('politics', 'I refused the king\'s commission. He is displeased.', { mood: 'anxious' });
                if (typeof UI !== 'undefined' && UI.toast) UI.toast('❌ Commission refused. (-' + result.repLoss + ' reputation)', 'warning');
            }
        }
        return result;
    }

    function deliverKingCommission(kingdomId) {
        if (!kingdomId) kingdomId = player.citizenshipKingdomId;
        if (!kingdomId) return { success: false, message: 'No kingdom specified.' };
        var result = Engine.deliverDirectedCommission(kingdomId);
        if (result && result.success) {
            player.reputation[kingdomId] = Math.min(100, (player.reputation[kingdomId] || 50) + result.repReward);
            player.gold += result.reward;
            grantXP(result.reward / 10, 'commission');
            autoJournalCapture('politics', 'I delivered on the king\'s commission! Earned ' + result.reward + 'g and the king\'s favor.', { mood: 'proud' });
            if (typeof UI !== 'undefined' && UI.toast) UI.toast('✅ Commission delivered! +' + result.reward + 'g, +' + result.repReward + ' rep!', 'success');
            // Notify story mode — commission goods count toward kingdom supply
            if (result.resourceId && result.qty && typeof StoryMode !== 'undefined' && StoryMode.onPlayerAction) {
                StoryMode.onPlayerAction('deliver_commission', { item: result.resourceId, qty: result.qty, kingdomId: kingdomId });
            }
        }
        return result;
    }

    function getActiveKingCommission(kingdomId) {
        if (!kingdomId) kingdomId = player.citizenshipKingdomId;
        if (!kingdomId) return null;
        try { return Engine.getDirectedPlayerCommission(kingdomId); } catch(e) { return null; }
    }

    // ========================================================
    // §11.5B2a LORD/RA — KINGDOM BUILDING CONSTRUCTION
    // Lords can build kingdom buildings in their lord town with king permission.
    // Royal Advisors can do this in any town (harder outside their lord town).
    // ========================================================

    // Top-level lord demotion handler — clears lordTownId and returns kingdom buildings
    function handleLordDemotion(kingdomId) {
        if (player.lordTownId) {
            var lordTown = Engine.findTown(player.lordTownId);
            if (lordTown && lordTown.kingdomId === kingdomId) {
                var kingdom = null;
                try { kingdom = Engine.findKingdom(kingdomId); } catch(e) {}
                if (kingdom && lordTown.buildings) {
                    for (var _bi = 0; _bi < lordTown.buildings.length; _bi++) {
                        var _b = lordTown.buildings[_bi];
                        if (_b._wasKingdomOwned && _b.ownerId === 'player') {
                            _b.ownerId = kingdom.id;
                            delete _b._wasKingdomOwned;
                        }
                    }
                }
            }
            player.lordTownId = null;
        }
    }

    var KINGDOM_BUILDING_TYPES = ['walls', 'barracks', 'watchtower', 'castle', 'granary', 'marketplace', 'temple', 'library', 'stables', 'armory', 'harbor_fortification'];

    function getKingdomBuildableTypes(townId) {
        var town = Engine.findTown(townId || player.townId);
        if (!town) return [];
        var existing = {};
        if (town.buildings) {
            for (var i = 0; i < town.buildings.length; i++) {
                existing[town.buildings[i].type] = true;
            }
        }
        var available = [];
        for (var bi = 0; bi < KINGDOM_BUILDING_TYPES.length; bi++) {
            var bType = KINGDOM_BUILDING_TYPES[bi];
            if (existing[bType]) continue;
            var bt = Engine.findBuildingType ? Engine.findBuildingType(bType) : null;
            if (!bt) continue;
            if (bType === 'harbor_fortification' && !town.isPort) continue;
            available.push({ id: bType, name: bt.name || bType, cost: bt.cost || 500, description: bt.description || '' });
        }
        return available;
    }

    function requestKingdomBuilding(townId, buildingType, playerContribution) {
        var kId = player.citizenshipKingdomId;
        var rank = player.socialRank[kId] || 0;
        if (rank < 5) return { success: false, message: 'Must be at least a Lord to request kingdom buildings.' };

        var town = Engine.findTown(townId);
        if (!town) return { success: false, message: 'Invalid town.' };
        if (town.kingdomId !== kId) return { success: false, message: 'Town is not in your kingdom.' };

        // Lords can only build in their lord town; RAs can build anywhere
        var isLordTown = (player.lordTownId === townId);
        if (rank === 5 && !isLordTown) {
            return { success: false, message: 'As a Lord, you can only request kingdom buildings in your lord town (' + (Engine.findTown(player.lordTownId) || {}).name + ').' };
        }

        var bt = Engine.findBuildingType ? Engine.findBuildingType(buildingType) : null;
        if (!bt) return { success: false, message: 'Unknown building type.' };
        var totalCost = bt.cost || 500;
        playerContribution = Math.max(0, Math.min(totalCost, Math.floor(playerContribution || 0)));
        var kingdomCost = totalCost - playerContribution;

        // Check player can afford their contribution
        if (player.gold < playerContribution) return { success: false, message: 'Cannot afford your ' + playerContribution + 'g contribution.' };

        // King approval AI
        var kingdom = null;
        try { kingdom = Engine.findKingdom(kId); } catch(e) {}
        if (!kingdom) return { success: false, message: 'Kingdom not found.' };

        var kingPerson = kingdom.king ? Engine.findPerson(kingdom.king) : null;
        var kingRel = kingPerson ? getRelationship(kingPerson.id).level : 50;
        var kRep = player.reputation[kId] || 50;
        var kGold = kingdom.gold || 0;
        var kp = kingdom.kingPersonality || {};

        // Base approval chance
        var approval = 0.20;

        // Relationship factor (0-30%)
        approval += (kingRel / 100) * 0.30;

        // Reputation factor (0-15%)
        approval += (kRep / 100) * 0.15;

        // Player contribution factor (huge — paying more = much more likely)
        var contributionRatio = playerContribution / totalCost;
        approval += contributionRatio * 0.30;

        // Kingdom treasury — can they afford it?
        if (kingdomCost > kGold * 0.3) approval -= 0.20;
        else if (kingdomCost > kGold * 0.1) approval -= 0.05;
        if (kingdomCost === 0) approval += 0.15;

        // King personality
        if (kp.generosity === 'generous') approval += 0.10;
        else if (kp.generosity === 'greedy') approval -= 0.15;
        if (kp.tradition === 'progressive') approval += 0.05;

        // Military buildings during wartime
        var isAtWar = kingdom.atWar && kingdom.atWar.size > 0;
        var isMilitary = ['barracks', 'watchtower', 'armory', 'walls', 'harbor_fortification'].indexOf(buildingType) >= 0;
        if (isAtWar && isMilitary) approval += 0.20;
        if (isAtWar && !isMilitary) approval -= 0.10;

        // RA building outside lord town — harder
        if (rank >= 6 && !isLordTown) approval -= 0.15;

        // Player-influenced king bonus
        if (kingdom._playerInfluencedKingDay && (Engine.getDay() - kingdom._playerInfluencedKingDay) < CONFIG.DAYS_PER_SEASON) {
            approval += 0.15;
        }

        approval = Math.max(0.05, Math.min(0.95, approval));

        var rng = Engine.getRng();
        var approved = rng && rng.chance ? rng.chance(approval) : Math.random() < approval;

        if (approved) {
            // Deduct costs
            player.gold -= playerContribution;
            player.stats.totalGoldSpent += playerContribution;
            if (kingdom.gold >= kingdomCost) kingdom.gold -= kingdomCost;

            // Build it
            town.buildings = town.buildings || [];
            town.buildings.push({
                type: buildingType,
                level: 1,
                ownerId: kingdom.id,
                builtDay: Engine.getDay(),
                condition: 100,
                lastRepairDay: 0,
                _requestedByPlayer: true
            });

            Engine.logEvent('🏗️ The king approved ' + player.fullName + '\'s request to build a ' + (bt.name || buildingType) + ' in ' + town.name + '! (Player: ' + playerContribution + 'g, Kingdom: ' + kingdomCost + 'g)');
            if (typeof UI !== 'undefined' && UI.toast) UI.toast('🏗️ ' + (bt.name || buildingType) + ' approved! Building in ' + town.name + '.', 'success');
            autoJournalCapture('politics', 'The king approved my request to build a ' + (bt.name || buildingType) + ' in ' + town.name + '.', { mood: 'pleased' });
            grantXP(25, 'Kingdom building request');
            return { success: true, approved: true, message: 'The king approved your request! A ' + (bt.name || buildingType) + ' is being built in ' + town.name + '. (Player: ' + playerContribution + 'g, Kingdom: ' + kingdomCost + 'g)', approvalChance: Math.round(approval * 100) };
        } else {
            Engine.logEvent('❌ The king denied ' + player.fullName + '\'s request to build a ' + (bt.name || buildingType) + ' in ' + town.name + '.');
            if (typeof UI !== 'undefined' && UI.toast) UI.toast('❌ King denied building request.', 'warning');
            return { success: true, approved: false, message: 'The king denied your request to build a ' + (bt.name || buildingType) + '. Try improving your relationship or offering more gold. (Chance was ~' + Math.round(approval * 100) + '%)', approvalChance: Math.round(approval * 100) };
        }
    }

    // ========================================================
    // §11.5B2b RA — KING SPECIAL FAVORS (Player-side)
    // ========================================================
    function getKingFavor(kingdomId) {
        var kId = kingdomId || player.royalAdvisorKingdomId || player.citizenshipKingdomId;
        if (!kId) return null;
        try {
            var kingdom = Engine.findKingdom(kId);
            return kingdom ? kingdom._pendingRAFavor : null;
        } catch(e) { return null; }
    }

    function respondToKingFavor(kingdomId, accept) {
        var kId = kingdomId || player.royalAdvisorKingdomId || player.citizenshipKingdomId;
        if (!kId) return { success: false, message: 'No kingdom.' };
        var kingdom = null;
        try { kingdom = Engine.findKingdom(kId); } catch(e) {}
        if (!kingdom || !kingdom._pendingRAFavor) return { success: false, message: 'No pending favor.' };

        var favor = kingdom._pendingRAFavor;

        if (accept) {
            // Check if player can afford
            if (favor.goldCost && player.gold < favor.goldCost) {
                return { success: false, message: 'Cannot afford the ' + favor.goldCost + 'g cost.' };
            }
            if (favor.goldCost) {
                player.gold -= favor.goldCost;
                player.stats.totalGoldSpent += favor.goldCost;
                if (kingdom.gold != null) kingdom.gold += favor.goldCost;
            }
            // Rewards
            player.reputation[kId] = Math.min(100, (player.reputation[kId] || 50) + (favor.repGain || 1));
            if (kingdom.king) modifyRelationship(kingdom.king, favor.relGain || 5, 'king_favor_accepted');
            kingdom._pendingRAFavor = null;

            Engine.logEvent('✅ ' + player.fullName + ' fulfilled the king\'s request: ' + favor.description + '.');
            if (typeof UI !== 'undefined' && UI.toast) UI.toast('✅ Favor fulfilled! +' + (favor.repGain || 3) + ' rep, +' + (favor.relGain || 5) + ' king relationship.', 'success');
            autoJournalCapture('politics', 'I fulfilled the king\'s request to ' + favor.description + '. The king is pleased.', { mood: 'pleased' });
            return { success: true, message: 'Favor fulfilled!' };
        } else {
            // Decline — hurts relationship
            if (kingdom.king) modifyRelationship(kingdom.king, -5, 'king_favor_declined');
            kingdom._pendingRAFavor = null;

            Engine.logEvent('❌ ' + player.fullName + ' declined the king\'s request: ' + favor.description + '.');
            if (typeof UI !== 'undefined' && UI.toast) UI.toast('❌ Favor declined. -5 king relationship.', 'warning');
            autoJournalCapture('politics', 'I declined the king\'s request to ' + favor.description + '. The king was displeased.', { mood: 'worried' });
            return { success: true, message: 'Favor declined. King relationship -5.' };
        }
    }

    // ========================================================
    // §11.5B3 ROYAL ADVISOR — PROPOSE LAWS (Player-side)
    // ========================================================

    function proposeLaw(kingdomId, lawId) {
        if (!kingdomId) kingdomId = player.royalAdvisorKingdomId || player.citizenshipKingdomId;
        if (!kingdomId) return { success: false, message: 'No kingdom specified.' };
        var rank = player.socialRank[kingdomId] || 0;
        if (rank < 6) return { success: false, message: 'Only Royal Advisors can propose laws.' };

        if (player.politicalCapital <= 0) return { success: false, message: 'No political capital remaining this season.' };

        var result = Engine.proposeLaw(kingdomId, lawId);
        if (result && result.success) {
            if (result.accepted) {
                grantXP(75, 'propose_law');
                autoJournalCapture('politics', 'I proposed ' + result.law + ' and the king agreed! The law is now in effect.', { mood: 'triumphant' });
            } else {
                autoJournalCapture('politics', 'I proposed ' + result.law + ' but the king rejected it. Perhaps I should try a different approach.', { mood: 'disappointed' });
            }
        }
        return result;
    }

    function getProposableLaws(kingdomId) {
        if (!kingdomId) kingdomId = player.royalAdvisorKingdomId || player.citizenshipKingdomId;
        if (!kingdomId) return [];
        try { return Engine.getProposableLaws(kingdomId); } catch(e) { return []; }
    }

    // ========================================================
    // §11.5B4 GRADUATION CEREMONIES — Rank Promotion Events
    // ========================================================

