    function hireArmedEscort(days) {
        days = Number(days);
        if (!days || !isFinite(days) || days <= 0) return { success: false, message: 'Invalid escort duration.' };
        days = Math.floor(days);
        var cost = days * CONFIG.WARTIME_ESCORT_COST_PER_DAY;
        if (player.gold < cost) return { success: false, message: 'Need ' + cost + 'g for ' + days + ' days of armed escort.' };
        player.gold -= cost;
        player.stats.totalGoldSpent += cost;
        player.armedEscort = { active: true, daysLeft: days };
        Engine.logEvent(player.fullName + ' hired an armed escort for ' + days + ' days (' + cost + 'g).');
        return { success: true, message: '⚔️ Armed escort hired for ' + days + ' days. (-' + cost + 'g)' };
    }

    // ========================================================
    // §12K-NEW  PLAYER ENCOUNTER SYSTEM (Bandits / Pirates / Wartime)
    // ========================================================

    function getMaxGuards() {
        var rankByRank = CONFIG.PLAYER_GUARD_MAX_BY_RANK;
        if (rankByRank) {
            // Use current location's kingdom rank, fallback to active citizenship
            var kId = null;
            try {
                var _gmTown = Engine.findTown(player.townId);
                if (_gmTown) kId = _gmTown.kingdomId;
            } catch(e) {}
            if (!kId) kId = player.citizenshipKingdomId || Object.keys(player.socialRank || {})[0];
            var rankIdx = kId ? (player.socialRank[kId] || 0) : 0;
            if (rankByRank[rankIdx] != null) return rankByRank[rankIdx];
        }
        return CONFIG.PLAYER_GUARD_MAX || 4;
    }

    function hirePersonalGuard() {
        if (!player.townId || player.traveling) return { success: false, message: 'Must be in a town to hire guards.' };
        var maxGuards = getMaxGuards();
        player.guards = player.guards || [];
        if (player.guards.length >= maxGuards) return { success: false, message: 'Already at maximum ' + maxGuards + ' guards.' };
        var cost = CONFIG.PLAYER_GUARD_HIRE_COST || 30;
        if (hasSkill('cheap_security')) cost = Math.floor(cost * 0.80);

        // Story mode: first guard is free
        var isFirstStoryGuard = player.storyMode && player.storyMode.active && player.guards.length === 0 && !player.storyMode._firstGuardHired;
        if (!isFirstStoryGuard && player.gold < cost) return { success: false, message: 'Need ' + cost + 'g to hire a guard.' };

        // Find a suitable NPC from the current town
        var townPeople = Engine.getPeople ? Engine.getPeople(player.townId) : [];
        var existingGuardIds = {};
        for (var gi = 0; gi < player.guards.length; gi++) {
            if (player.guards[gi].personId) existingGuardIds[player.guards[gi].personId] = true;
        }
        var _playerEmployees = {};
        if (player.employees) { for (var _ei = 0; _ei < player.employees.length; _ei++) _playerEmployees[player.employees[_ei]] = true; }
        var _opTown = Engine.findTown(player.townId);
        var _opWorkers = {};
        if (_opTown && _opTown.outpostWorkers) { for (var _owi = 0; _owi < _opTown.outpostWorkers.length; _owi++) _opWorkers[_opTown.outpostWorkers[_owi]] = true; }
        if (_opTown && _opTown.outpostGuards) { for (var _ogi = 0; _ogi < _opTown.outpostGuards.length; _ogi++) _opWorkers[_opTown.outpostGuards[_ogi]] = true; }
        var candidates = [];
        for (var ci = 0; ci < townPeople.length; ci++) {
            var p = townPeople[ci];
            if (!p.alive || p.age < 18) continue;
            if (existingGuardIds[p.id]) continue;
            if (p.id === player.spouseId) continue;
            if (p.isPlayerGuard) continue;
            if (p.traveling) continue;
            if (_playerEmployees[p.id]) continue;
            if (_opWorkers[p.id]) continue;
            if (p.occupation === 'outpost_worker') continue;
            if (p.isEliteMerchant || p.occupation === 'noble' || p.occupation === 'king') continue;
            var _highRank = false;
            if (p.socialRank) {
                for (var _rk in p.socialRank) {
                    if ((p.socialRank[_rk] || 0) >= 2) { _highRank = true; break; }
                }
            }
            if (_highRank) continue;
            candidates.push(p);
        }
        if (candidates.length === 0) return { success: false, message: 'No hireable guards in this location.' };

        // Pick a candidate — prefer soldiers/unemployed
        var rng = Engine.getRng();
        var preferred = candidates.filter(function(c) {
            return c.occupation === 'soldier' || c.occupation === 'guard' || c.occupation === 'unemployed' || !c.occupation;
        });
        var chosen = preferred.length > 0 ? (rng.pick ? rng.pick(preferred) : preferred[Math.floor(rng.random() * preferred.length)])
            : (rng.pick ? rng.pick(candidates) : candidates[Math.floor(rng.random() * candidates.length)]);

        if (isFirstStoryGuard) {
            // First story guard is free — mark so it only happens once
            player.storyMode._firstGuardHired = true;
        } else {
            player.gold -= cost;
            logFinance(-cost, 'guards', 'Hired personal guard');
        }

        // Mark NPC as player guard
        chosen.isPlayerGuard = true;
        chosen.previousOccupation = chosen.occupation;
        chosen.previousTownId = chosen.townId;
        chosen.occupation = 'player_guard';

        var guardName = (chosen.firstName || '') + (chosen.lastName ? ' ' + chosen.lastName : '');
        if (!guardName.trim()) guardName = 'Guard ' + (player.guards.length + 1);
        var guard = {
            id: 'guard_' + Date.now() + '_' + (rng ? rng.randInt(0, 9999) : Math.floor(Math.random() * 9999)),
            personId: chosen.id,
            name: guardName,
            hiredDay: Engine.getDay()
        };
        player.guards.push(guard);
        player.personalGuards = player.guards.length;

        if (isFirstStoryGuard) {
            Engine.logEvent('🛡️ ' + guardName + ' has volunteered to guard you — a favor owed to your father. (FREE)');
            // Show dialog from the guard NPC with gender-appropriate voice & portrait
            if (typeof UI !== 'undefined' && UI.queueStoryDialog) {
                var guardIsFemale = chosen.sex === 'F';
                var guardPortrait = chosen.portrait || (guardIsFemale ? '\u{1F482}\u{200D}\u{2640}\u{FE0F}' : '\u{1F482}');
                UI.queueStoryDialog({
                    speaker: guardName,
                    portrait: guardPortrait,
                    _dialogKey: guardIsFemale ? 'ch4b_first_guard_f' : 'ch4b_first_guard_m',
                    lines: [
                        "You're Edmund's {son|daughter}? Your father saved my life years ago. I owe him a debt I can never repay. Let me guard you on the roads \u2014 free of charge."
                    ]
                });
            }
        } else {
            Engine.logEvent('🛡️ Hired ' + guardName + ' as a personal guard for ' + cost + 'g. (' + player.guards.length + '/' + maxGuards + ')');
        }

        if (player.storyMode && player.storyMode.active && typeof StoryMode !== 'undefined' && StoryMode.onPlayerAction) {
            StoryMode.onPlayerAction('hire_guard', {});
        }

        var msg = isFirstStoryGuard
            ? '🛡️ ' + guardName + ' volunteers to guard you for free!'
            : '🛡️ ' + guardName + ' hired for ' + cost + 'g. (' + player.guards.length + '/' + maxGuards + ')';
        return { success: true, message: msg, guard: guard };
    }

    function dismissPersonalGuard(guardId) {
        player.guards = player.guards || [];
        if (player.guards.length === 0) return { success: false, message: 'No guards to dismiss.' };
        var idx = -1;
        if (guardId) {
            for (var i = 0; i < player.guards.length; i++) {
                if (player.guards[i].id === guardId) { idx = i; break; }
            }
        }
        if (idx === -1) idx = player.guards.length - 1;
        var dismissed = player.guards[idx];
        var name = dismissed.name;

        // Return NPC to current town
        if (dismissed.personId && Engine.getPerson) {
            var npc = Engine.getPerson(dismissed.personId);
            if (npc && npc.alive) {
                npc.isPlayerGuard = false;
                npc.occupation = npc.previousOccupation || 'unemployed';
                npc.townId = player.townId || npc.previousTownId || npc.townId;
                delete npc.previousOccupation;
                delete npc.previousTownId;
            }
        }

        player.guards.splice(idx, 1);
        player.personalGuards = player.guards.length;
        Engine.logEvent('\uD83D\uDEE1\uFE0F Dismissed guard ' + name + '. (' + player.guards.length + '/' + getMaxGuards() + ')');
        return { success: true, message: '\uD83D\uDEE1\uFE0F Dismissed ' + name + '. (' + player.guards.length + '/' + getMaxGuards() + ')' };
    }

    function tickPersonalGuardWages() {
        player.guards = player.guards || [];
        if (player.guards.length === 0) return;

        // Sync guard NPC locations with player + remove dead guards
        for (var gi = player.guards.length - 1; gi >= 0; gi--) {
            var g = player.guards[gi];
            if (g.personId && Engine.getPerson) {
                var npc = Engine.getPerson(g.personId);
                if (!npc || !npc.alive) {
                    Engine.logEvent('💀 Your guard ' + g.name + ' has died.');
                    player.guards.splice(gi, 1);
                    continue;
                }
                // Guard follows player
                npc.townId = player.townId;
            }
        }
        player.personalGuards = player.guards.length;
        if (player.guards.length === 0) return;

        var wage = (CONFIG.PLAYER_GUARD_DAILY_WAGE || 6) * player.guards.length;
        // Kingdom-paid guards (granted on noble promotion) have wages paid by the kingdom
        var kingdomPaidGuards = player.guards.filter(function(g) { return g.kingdomPaid; });
        var playerPaidWage = (CONFIG.PLAYER_GUARD_DAILY_WAGE || 6) * (player.guards.length - kingdomPaidGuards.length);
        var kingdomPaidWage = (CONFIG.PLAYER_GUARD_DAILY_WAGE || 6) * kingdomPaidGuards.length;
        if (kingdomPaidWage > 0 && player.citizenshipKingdomId) {
            var guardKingdom = Engine.findKingdom(player.citizenshipKingdomId);
            if (guardKingdom && (guardKingdom.gold || 0) >= kingdomPaidWage) {
                guardKingdom.gold -= kingdomPaidWage;
            } else {
                // Kingdom can't afford — player must pay
                playerPaidWage += kingdomPaidWage;
            }
        }
        player.gold -= playerPaidWage;
        if (playerPaidWage > 0) logFinance(-playerPaidWage, 'guards', 'Guard wages (' + (player.guards.length - kingdomPaidGuards.length) + ')');
        if (player.gold < 0) {
            while (player.gold < 0 && player.guards.length > 0) {
                var dismissed = player.guards.pop();
                player.gold += (CONFIG.PLAYER_GUARD_DAILY_WAGE || 6);
                // Return NPC to current town
                if (dismissed.personId && Engine.getPerson) {
                    var dnpc = Engine.getPerson(dismissed.personId);
                    if (dnpc && dnpc.alive) {
                        dnpc.isPlayerGuard = false;
                        dnpc.occupation = dnpc.previousOccupation || 'unemployed';
                        dnpc.townId = player.townId || dnpc.previousTownId || dnpc.townId;
                        delete dnpc.previousOccupation;
                        delete dnpc.previousTownId;
                    }
                }
                Engine.logEvent('\uD83D\uDCB8 ' + dismissed.name + ' leaves \u2014 you can\'t afford the wages. (' + player.guards.length + ' remaining)');
            }
            if (player.gold < 0) player.gold = 0;
        }
        player.personalGuards = player.guards.length;
    }

    function getEncounterChance() {
        var rng = Engine.getRng();
        if (!rng) return { chance: 0, riskLevel: 'none', isWartime: false, isSea: false };

        // Check current segment type — mixed routes have both land and sea segments
        var isSea = false;
        if (player.travelBySea && player.travelRoute && player.travelRoute.length > 0) {
            var segIdx = Math.min(Math.floor((player.travelProgress || 0) * player.travelRoute.length), player.travelRoute.length - 1);
            isSea = player.travelRoute[segIdx] && player.travelRoute[segIdx].type === 'sea';
        } else if (player.travelBySea) {
            isSea = true; // fallback if no route segments
        }
        var isWartime = isInWarzone();
        var chance;

        if (isSea) {
            // Sea: ship defense is main factor
            chance = CONFIG.ENCOUNTER_SEA_BASE_CHANCE || 0.04;
            // Off-sea-route travel has higher pirate risk
            if (player.travelOffSea && player._offSeaPirateChance) {
                chance = Math.max(chance, player._offSeaPirateChance);
            }
            var ship = getBestShip();
            if (ship) {
                var def = getShipDefense(ship);
                var factor = CONFIG.ENCOUNTER_SEA_SHIP_DEFENSE_FACTOR || 0.06;
                chance *= Math.max(0.05, 1.0 - def * factor);
            }
            // Guards moderate help at sea
            var guards = (player.guards || []).length;            for (var g = 0; g < guards; g++) {
                chance *= (CONFIG.ENCOUNTER_SEA_GUARD_REDUCTION || 0.70);
            }
            if (hasSkill('veteran_guards') && guards > 0) chance *= 0.70;
            // Weapons/armor tiny help at sea
            if (player.weapon) chance *= (CONFIG.ENCOUNTER_SEA_WEAPON_REDUCTION || 0.97);
            if (player.armor) chance *= (CONFIG.ENCOUNTER_SEA_ARMOR_REDUCTION || 0.98);
            // Skills
            if (hasSkill('street_smart')) chance *= (CONFIG.ENCOUNTER_SKILL_STREET_SMART || 0.90);
            if (hasSkill('intimidating_presence')) chance *= (CONFIG.ENCOUNTER_SKILL_INTIMIDATING || 0.85);
            if (hasSkill('expert_navigator')) chance *= 0.90;
            // Bandit evasion skills (sea pirates too)
            if (!isWartime) {
                if (hasSkill('bandit_mastery')) chance *= 0.50;
                else if (hasSkill('bandit_evasion')) chance *= 0.75;
            } else {
                if (hasSkill('bandit_mastery')) chance *= 0.75;
            }
            // Pirate events
            var w = Engine.getWorld();
            if (w) {
                for (var ei = 0; ei < w.events.length; ei++) {
                    if (w.events[ei].active && w.events[ei].type === 'pirates') chance *= (w.events[ei].seaRiskMultiplier || 3);
                }
            }
            // Clamp
            chance = Math.max(CONFIG.ENCOUNTER_SEA_MIN_CHANCE || 0.0001, Math.min(CONFIG.ENCOUNTER_SEA_MAX_CHANCE || 0.10, chance));
        } else {
            // Land encounters
            chance = CONFIG.ENCOUNTER_LAND_BASE_CHANCE || 0.05;
            // Road danger
            if (player.travelRoute && player.travelRoute.length > 0) {
                var currentSegIdx = Math.min(Math.floor(player.travelProgress * player.travelRoute.length), player.travelRoute.length - 1);
                var seg = player.travelRoute[currentSegIdx];
                if (seg) {
                    if (seg.safe === false || (seg.banditThreat || 0) > 50) {
                        chance *= (CONFIG.ENCOUNTER_ROAD_DANGER_MULT || 1.5);
                    }
                    // Check connected town security
                    var destTown = Engine.findTown(seg.toTownId);
                    var fromTown = Engine.findTown(seg.fromTownId);
                    if (destTown && (destTown.security || 50) < 30) chance *= (CONFIG.ENCOUNTER_POOR_SECURITY_MULT || 1.3);
                    if (fromTown && (fromTown.security || 50) < 30) chance *= (CONFIG.ENCOUNTER_POOR_SECURITY_MULT || 1.3);
                }
            }
            // Guards
            var guards2 = player.personalGuards || 0;
            for (var g2 = 0; g2 < guards2; g2++) {
                chance *= (1.0 - (CONFIG.ENCOUNTER_GUARD_REDUCTION || 0.40));
            }
            if (hasSkill('veteran_guards') && guards2 > 0) chance *= 0.70;
            // Horse
            if (player.horses && player.horses.length > 0) chance *= (CONFIG.ENCOUNTER_HORSE_REDUCTION || 0.85);
            // Paid transit
            if (player.travelPaid) chance *= (CONFIG.ENCOUNTER_PAID_TRANSIT_REDUCTION || 0.25);
            // Weapons/armor
            if (player.weapon) chance *= (CONFIG.ENCOUNTER_WEAPON_REDUCTION || 0.90);
            if (player.armor) chance *= (CONFIG.ENCOUNTER_ARMOR_REDUCTION || 0.93);
            // Skills
            if (hasSkill('street_smart')) chance *= (CONFIG.ENCOUNTER_SKILL_STREET_SMART || 0.90);
            if (hasSkill('intimidating_presence')) chance *= (CONFIG.ENCOUNTER_SKILL_INTIMIDATING || 0.85);
            if (hasSkill('road_knowledge')) chance *= 0.92;
            // Bandit evasion skills
            if (!isWartime) {
                if (hasSkill('bandit_mastery')) chance *= 0.50;
                else if (hasSkill('bandit_evasion')) chance *= 0.75;
            } else {
                if (hasSkill('bandit_mastery')) chance *= 0.75;
            }
            // Clamp
            chance = Math.max(CONFIG.ENCOUNTER_LAND_MIN_CHANCE || 0.001, Math.min(CONFIG.ENCOUNTER_LAND_MAX_CHANCE || 0.15, chance));
        }

        // Wartime multiplier
        if (isWartime) {
            chance *= (CONFIG.ENCOUNTER_WARTIME_CHANCE_MULT || 1.8);
            // Re-clamp after wartime mult
            var maxChance = isSea ? (CONFIG.ENCOUNTER_SEA_MAX_CHANCE || 0.10) : (CONFIG.ENCOUNTER_LAND_MAX_CHANCE || 0.15);
            chance = Math.min(maxChance, chance);
        }

        // War allegiance penalty: +50% encounters in enemy kingdom territory
        var inEnemyTerritory = false;
        if (player.warAllegiances && player.travelRoute && player.travelRoute.length > 0) {
            var _ecSegIdx = Math.min(Math.floor((player.travelProgress || 0) * player.travelRoute.length), player.travelRoute.length - 1);
            var _ecSeg = player.travelRoute[_ecSegIdx];
            if (_ecSeg) {
                var _ecTown = Engine.findTown(_ecSeg.toTownId) || Engine.findTown(_ecSeg.fromTownId);
                if (_ecTown) {
                    for (var _ecWid in player.warAllegiances) {
                        var _ecAlleg = player.warAllegiances[_ecWid];
                        if (_ecAlleg.side && _ecAlleg.side !== 'neutral') {
                            var _ecActiveWars = Engine.getActiveWars ? Engine.getActiveWars() : {};
                            var _ecWar = _ecActiveWars[_ecWid];
                            if (_ecWar) {
                                var _ecEnemy = (_ecAlleg.side === _ecWar.kingdomA) ? _ecWar.kingdomB : _ecWar.kingdomA;
                                if (_ecTown.kingdomId === _ecEnemy) { inEnemyTerritory = true; break; }
                            }
                        }
                    }
                }
            }
        }
        if (inEnemyTerritory) {
            chance *= 1.5; // +50% encounter chance in enemy territory
        }

        // God mode: force 95% encounter chance
        if (typeof window !== 'undefined' && window._godBanditBoost) chance = 0.95;

        // Determine risk level
        var riskLevel = 'low';
        if (chance >= 0.06) riskLevel = 'high';
        else if (chance >= 0.025) riskLevel = 'medium';

        return { chance: chance, riskLevel: riskLevel, isWartime: isWartime, isSea: isSea };
    }

    function isInWarzone() {
        if (!player.travelRoute || player.travelRoute.length === 0) return false;
        var activeWars = Engine.getActiveWars ? Engine.getActiveWars() : {};
        if (!activeWars || Object.keys(activeWars).length === 0) return false;
        for (var i = 0; i < player.travelRoute.length; i++) {
            var seg = player.travelRoute[i];
            var fromTown = Engine.findTown(seg.fromTownId);
            var toTown = Engine.findTown(seg.toTownId);
            if (!fromTown || !toTown) continue;
            for (var warId in activeWars) {
                var war = activeWars[warId];
                if (!war) continue;
                var sides = war.sides || [war.attackerId, war.defenderId];
                if (sides.length < 2) continue;
                var fromSide = sides.indexOf(fromTown.kingdomId);
                var toSide = sides.indexOf(toTown.kingdomId);
                if (fromSide >= 0 && toSide >= 0 && fromSide !== toSide) return true;
            }
        }
        return false;
    }

    function _isInEnemyWarTerritory() {
        if (!player.warAllegiances || !player.travelRoute || player.travelRoute.length === 0) return false;
        var segIdx = Math.min(Math.floor((player.travelProgress || 0) * player.travelRoute.length), player.travelRoute.length - 1);
        var seg = player.travelRoute[segIdx];
        if (!seg) return false;
        var town = Engine.findTown(seg.toTownId) || Engine.findTown(seg.fromTownId);
        if (!town) return false;
        var activeWars = Engine.getActiveWars ? Engine.getActiveWars() : {};
        for (var wid in player.warAllegiances) {
            var alleg = player.warAllegiances[wid];
            if (!alleg.side || alleg.side === 'neutral') continue;
            var war = activeWars[wid];
            if (!war) continue;
            var enemy = (alleg.side === war.kingdomA) ? war.kingdomB : war.kingdomA;
            if (town.kingdomId === enemy) return true;
        }
        return false;
    }

    function checkDailyEncounter() {
        if (!player.traveling) return;
        if (player.encounterPending) return; // already awaiting resolution
        // Story Mode: suppress random encounters
        if (player.storyMode && player.storyMode.active && player.storyMode.flags && player.storyMode.flags.suppressEncounters) return;
        var rng = Engine.getRng();
        if (!rng) return;

        var info = getEncounterChance();
        if (info.chance <= 0) return;

        if (!rng.chance(info.chance)) return;

        // Encounter triggered! Pause game and show choice dialog
        var isSea = info.isSea;
        var isWartime = info.isWartime;

        // Determine bandit strength (RNG element)
        var banditStrength = (CONFIG.ENCOUNTER_FIGHT_BANDIT_STRENGTH_MIN || 0.10) +
            rng.random() * ((CONFIG.ENCOUNTER_FIGHT_BANDIT_STRENGTH_MAX || 0.30) - (CONFIG.ENCOUNTER_FIGHT_BANDIT_STRENGTH_MIN || 0.10));
        if (isWartime) banditStrength *= (CONFIG.ENCOUNTER_WARTIME_FIGHT_DIFFICULTY || 1.4);

        // Enemy territory: encounters are 25% more dangerous
        if (_isInEnemyWarTerritory()) banditStrength *= 1.25;

        // Calculate fight win chance
        var fightWin = calculateFightWinChance(isSea, isWartime, banditStrength);

        // Calculate negotiate success chance
        var negotiateChance = CONFIG.ENCOUNTER_NEGOTIATE_BASE_SUCCESS || 0.40;
        if (hasSkill('silver_tongue') || (player.heirTraits && player.heirTraits.indexOf('silver_tongue') >= 0)) negotiateChance += (CONFIG.ENCOUNTER_NEGOTIATE_SKILL_BONUS || 0.15);
        if (hasSkill('escape_artist')) negotiateChance += 0.10;
        if (hasSkill('street_smart')) negotiateChance += 0.10;
        negotiateChance = Math.min(0.90, Math.max(0.10, negotiateChance));

        player.encounterPending = {
            isSea: isSea,
            isWartime: isWartime,
            banditStrength: banditStrength,
            fightWinChance: fightWin,
            negotiateChance: negotiateChance,
            day: Engine.getDay()
        };

        // Pause the game so player can make their choice
        if (typeof Engine.pause === 'function') Engine.pause();

        // Trigger the UI dialog
        if (typeof window._showEncounterDialog === 'function') {
            window._showEncounterDialog(player.encounterPending);
        }
    }

    function calculateFightWinChance(isSea, isWartime, banditStrength) {
        var win = CONFIG.ENCOUNTER_FIGHT_BASE_WIN || 0.35;

        // Guards
        var guards = (player.guards || []).length;
        if (isSea) {
            win += guards * (CONFIG.ENCOUNTER_SEA_FIGHT_GUARD_BONUS || 0.08);
        } else {
            win += guards * (CONFIG.ENCOUNTER_FIGHT_GUARD_BONUS || 0.12);
        }
        if (hasSkill('veteran_guards') && guards > 0) win += 0.10;

        // Weapons
        if (player.weapon) {
            var wBonus = isSea ? (CONFIG.ENCOUNTER_SEA_FIGHT_WEAPON_BONUS || 0.02) : (CONFIG.ENCOUNTER_FIGHT_WEAPON_BONUS || 0.10);
            if (typeof player.weapon === 'object') {
                win += wBonus * (player.weapon.combatBonus || 0.2) / 0.2;
            } else {
                win += wBonus;
            }
        }

        // Armor
        if (player.armor) {
            var aBonus = CONFIG.ENCOUNTER_FIGHT_ARMOR_BONUS || 0.05;
            if (typeof player.armor === 'object') {
                win += aBonus * (player.armor.combatBonus || 0.3) / 0.3;
            } else {
                win += aBonus;
            }
        }

        // Ship defense (sea only)
        if (isSea) {
            var ship = getBestShip();
            if (ship) {
                var def = getShipDefense(ship);
                win += def * (CONFIG.ENCOUNTER_SEA_FIGHT_SHIP_DEFENSE_BONUS || 0.02);
                win += (ship.cannons || 0) * (CONFIG.ENCOUNTER_SEA_FIGHT_CANNON_BONUS || 0.06);
            }
        }

        // Skills
        if (hasSkill('battle_hardened')) {
            win += (CONFIG.ENCOUNTER_FIGHT_SKILL_BATTLE_HARDENED || 0.20);
        } else if (hasSkill('combat_trained')) {
            win += (CONFIG.ENCOUNTER_FIGHT_SKILL_COMBAT_TRAINED || 0.10);
        }
        if (hasSkill('combat_proficiency')) win += (CONFIG.ENCOUNTER_FIGHT_SKILL_COMBAT_PROFICIENCY || 0.10);

        // Low needs penalty
        var penalty = CONFIG.ENCOUNTER_FIGHT_LOW_NEEDS_PENALTY || 0.08;
        if ((player.hunger || 100) < 20) win -= penalty;
        if ((player.thirst || 100) < 20) win -= penalty;
        if ((player.energy || 100) < 20) win -= penalty;

        // Bandit strength (RNG difficulty)
        win -= banditStrength;

        // Clamp
        win = Math.max(CONFIG.ENCOUNTER_FIGHT_MIN_WIN || 0.05, Math.min(CONFIG.ENCOUNTER_FIGHT_MAX_WIN || 0.95, win));
        return win;
    }

    function resolveEncounter(choice) {
        var enc = player.encounterPending;
        if (!enc) return { success: false, message: 'No encounter pending.' };

        var rng = Engine.getRng();
        if (!rng) rng = { random: Math.random, chance: function(c) { return Math.random() < c; } };

        var result = { choice: choice, success: false, goldLost: 0, goodsLost: {}, injured: false, injurySeverity: null, shipDamaged: false, died: false };
        var isSea = enc.isSea;
        var isWartime = enc.isWartime;
        var enemyName = isWartime ? (isSea ? 'enemy navy' : 'enemy soldiers') : (isSea ? 'pirates' : 'bandits');

        if (choice === 'surrender') {
            // Surrender: lose half of goods + 50% gold capped at 500g
            var goldPct = CONFIG.ENCOUNTER_SURRENDER_GOLD_PCT || 0.50;
            var goldCap = CONFIG.ENCOUNTER_SURRENDER_GOLD_CAP || 500;
            var goldLost = Math.min(Math.floor(player.gold * goldPct), goldCap);
            player.gold -= goldLost;
            result.goldLost = goldLost;
            logFinance(-goldLost, 'encounter', 'Surrendered to ' + enemyName);

            // Lose half of each inventory type
            for (var key in player.inventory) {
                if (player.inventory[key] > 0) {
                    var lostQty = Math.ceil(player.inventory[key] * 0.50);
                    result.goodsLost[key] = lostQty;
                    player.inventory[key] -= lostQty;
                }
            }

            result.success = true;
            var emoji = isWartime ? '🏳️' : '💰';
            Engine.logEvent(emoji + ' You surrendered to ' + enemyName + '. Lost ' + goldLost + 'g and half your goods.');
            autoJournalCapture('encounter', 'Surrendered to ' + enemyName + ' on the ' + (isSea ? 'seas' : 'road') + '. They took half of everything.', { mood: 'defeated' });

        } else if (choice === 'negotiate') {
            var negSuccess = rng.chance(enc.negotiateChance);

            if (negSuccess) {
                // Successful negotiation: lose 50% of goods (random) + 10% gold (cap 250g)
                var goldPct2 = CONFIG.ENCOUNTER_NEGOTIATE_GOLD_PCT || 0.10;
                var goldCap2 = CONFIG.ENCOUNTER_NEGOTIATE_GOLD_CAP || 250;
                var goldLost2 = Math.min(Math.floor(player.gold * goldPct2), goldCap2);
                player.gold -= goldLost2;
                result.goldLost = goldLost2;
                logFinance(-goldLost2, 'encounter', 'Negotiated with ' + enemyName);

                var goodsPct = CONFIG.ENCOUNTER_NEGOTIATE_GOODS_PCT || 0.25;
                // Lose quarter of each goods type quantity
                var invKeys = Object.keys(player.inventory).filter(function(k) { return player.inventory[k] > 0; });
                for (var ni = 0; ni < invKeys.length; ni++) {
                    var nkey = invKeys[ni];
                    var loseQty = Math.ceil(player.inventory[nkey] * goodsPct);
                    if (loseQty > 0) {
                        result.goodsLost[nkey] = loseQty;
                        player.inventory[nkey] -= loseQty;
                    }
                }

                result.success = true;
                Engine.logEvent('🤝 You negotiated with the ' + enemyName + '. Lost ' + goldLost2 + 'g and some goods, but kept the rest.');
                autoJournalCapture('encounter', 'Managed to talk my way through a ' + enemyName + ' encounter. Lost some goods but kept my life.', { mood: 'relieved' });
            } else {
                // Failed negotiation — becomes a fight (with penalty)
                var fightWin = Math.max(CONFIG.ENCOUNTER_FIGHT_MIN_WIN || 0.05, enc.fightWinChance - 0.10);
                result = resolveFight(rng, fightWin, isSea, isWartime, enemyName);
                result.choice = 'negotiate_failed';
                Engine.logEvent('❌ Negotiation failed! The ' + enemyName + ' attacked!');
            }

        } else if (choice === 'fight') {
            result = resolveFight(rng, enc.fightWinChance, isSea, isWartime, enemyName);
            result.choice = 'fight';
        }

        player.encounterPending = null;
        // Resume game
        if (typeof Engine.unpause === 'function') Engine.unpause();
        return result;
    }

    function resolveFight(rng, winChance, isSea, isWartime, enemyName) {
        var result = { success: false, goldLost: 0, goodsLost: {}, injured: false, injurySeverity: null, shipDamaged: false, died: false };

        // Escape Artist: variable flee chance (5-30%) based on circumstances
        if (hasSkill('escape_artist')) {
            var fleeChance = 0.15; // base 15%
            // Horse gives big bonus on land
            if (!isSea && player.horses && player.horses.length > 0) fleeChance += 0.08;
            // High energy helps
            if ((player.energy || 100) >= 70) fleeChance += 0.05;
            else if ((player.energy || 100) < 30) fleeChance -= 0.05;
            // Good hunger/thirst helps
            if ((player.hunger || 100) >= 50 && (player.thirst || 100) >= 50) fleeChance += 0.03;
            else if ((player.hunger || 100) < 20 || (player.thirst || 100) < 20) fleeChance -= 0.03;
            // Sea is harder to flee on
            if (isSea) fleeChance -= 0.05;
            // Wartime soldiers are more organized
            if (isWartime) fleeChance -= 0.04;
            // Light armor bonus (no armor = nimble)
            if (!player.armor) fleeChance += 0.02;
            // Street smart helps
            if (hasSkill('street_smart')) fleeChance += 0.03;
            fleeChance = Math.max(0.05, Math.min(0.30, fleeChance));
            if (rng.chance(fleeChance)) {
                result.success = true;
                result.fled = true;
                Engine.logEvent('🏃 You used your wits to escape the ' + enemyName + ' without a fight!');
                autoJournalCapture('encounter', 'Managed to slip away from ' + enemyName + ' before the fighting started.', { mood: 'relieved' });
                return result;
            }
            // Flee failed — must fight
            Engine.logEvent('🏃 You tried to escape but the ' + enemyName + ' cut off your retreat!');
        }

        var won = rng.chance(winChance);

        // God mode invincibility
        if (window._godInvincible) won = true;

        if (won) {
            // Won the fight!
            result.success = true;
            Engine.logEvent('⚔️ You fought off the ' + enemyName + '!');
            grantXP(15); // combat XP

            // Sea: ship may take damage even on win
            if (isSea) {
                var dmgChance = CONFIG.ENCOUNTER_FIGHT_WIN_SHIP_DAMAGE_CHANCE || 0.40;
                if (rng.chance(dmgChance)) {
                    var ship = getBestShip();
                    if (ship) {
                        var dmg = 5 + Math.floor(rng.random() * 15);
                        ship.hullHealth = Math.max(0, (ship.hullHealth || 100) - dmg);
                        result.shipDamaged = true;
                        Engine.logEvent('🔨 Your ship took ' + dmg + ' hull damage in the fight.');
                    }
                }
            }

            autoJournalCapture('encounter', 'Fought off ' + enemyName + ' on the ' + (isSea ? 'seas' : 'road') + '. Victory!', { mood: 'proud' });
        } else {
            // Lost the fight
            result.success = false;

            if (isSea) {
                // Sea loss: wash up at destination with severe illness, lose all goods
                for (var key in player.inventory) {
                    if (player.inventory[key] > 0) {
                        result.goodsLost[key] = player.inventory[key];
                        player.inventory[key] = 0;
                    }
                }
                // Severe illness from washing ashore
                player.illnesses = player.illnesses || [];
                var seaIllness = { name: 'Waterlogged Fever', type: 'waterlogged_fever', severity: 'severe', dayOccurred: Engine.getDay(), treated: false, contagious: false, daysRemaining: 30 + Math.floor(rng.random() * 20) };
                player.illnesses.push(seaIllness);
                result.injured = true;
                result.injurySeverity = 'severe';
                // Ship may be damaged or destroyed
                var ship2 = getBestShip();
                if (ship2) {
                    var heavyDmg = 30 + Math.floor(rng.random() * 40);
                    ship2.hullHealth = Math.max(0, (ship2.hullHealth || 100) - heavyDmg);
                    result.shipDamaged = true;
                    if (ship2.hullHealth <= 0) {
                        Engine.logEvent('💀 Your ' + ship2.name + ' was destroyed by ' + enemyName + '!');
                        player.ships = player.ships.filter(function(s) { return s.id !== ship2.id; });
                    }
                }
                Engine.logEvent('💀 You lost the fight against ' + enemyName + '! You washed ashore ill and with nothing.');
                autoJournalCapture('encounter', 'Defeated by ' + enemyName + ' at sea. Washed ashore half-drowned with a terrible fever.', { mood: 'desperate' });
            } else {
                // Land loss: moderate or severe injury + lose all goods
                for (var key2 in player.inventory) {
                    if (player.inventory[key2] > 0) {
                        result.goodsLost[key2] = player.inventory[key2];
                        player.inventory[key2] = 0;
                    }
                }

                // Injury: moderate or severe
                var injuryMult = isWartime ? (CONFIG.ENCOUNTER_WARTIME_INJURY_MULT || 1.5) : 1.0;
                var severeChance = (CONFIG.ENCOUNTER_FIGHT_LOSS_INJURY_MODERATE_CHANCE || 0.50);
                // Armor reduces severe chance
                if (player.armor) {
                    var armorReduction = (typeof player.armor === 'object') ? (player.armor.combatBonus || 0.3) : 0.3;
                    severeChance *= (1.0 - armorReduction * 0.5);
                }
                if (isWartime) severeChance *= injuryMult;
                severeChance = Math.min(0.90, severeChance);

                var severity = rng.chance(severeChance) ? 'severe' : 'moderate';
                player.injuries = player.injuries || [];
                var injuryNames = isWartime
                    ? ['Sword Wound', 'Arrow Wound', 'Battle Trauma', 'Spear Wound', 'Shield Bash Concussion']
                    : ['Knife Wound', 'Blunt Trauma', 'Bandit Beating', 'Club Injury', 'Road Ambush Wound'];
                var injName = rng.pick ? rng.pick(injuryNames) : injuryNames[Math.floor(rng.random() * injuryNames.length)];
                var injType = severity === 'severe' ? 'encounter_wound_severe' : 'encounter_wound';
                player.injuries.push({ name: injName, type: injType, severity: severity, dayOccurred: Engine.getDay(), treated: false });
                Player._applyConditionHealthHit(severity);
                result.injured = true;
                result.injurySeverity = severity;

                // Small gold loss too
                var goldLost3 = Math.min(Math.floor(player.gold * 0.20), 200);
                player.gold -= goldLost3;
                result.goldLost = goldLost3;
                logFinance(-goldLost3, 'encounter', 'Robbed by ' + enemyName);

                // Death check (very small chance, higher in wartime)
                var deathChance = isWartime ? 0.05 : 0.02;
                if (player.armor) deathChance *= 0.5;
                if (hasSkill('battle_hardened')) deathChance *= 0.3;
                if (window._godInvincible) deathChance = 0;
                if (rng.chance(deathChance)) {
                    result.died = true;
                    player.deathCause = 'Killed by ' + enemyName;
                    Engine.logEvent('💀 ' + player.fullName + ' was killed by ' + enemyName + '!');
                    handlePlayerDeath();
                } else {
                    Engine.logEvent('⚔️ You lost the fight against ' + enemyName + '! Suffered a ' + severity + ' ' + injName + ' and lost all your goods.');
                }

                autoJournalCapture('encounter', 'Defeated by ' + enemyName + '. Suffered a ' + severity + ' injury. Lost everything I was carrying.', { mood: 'defeated' });
            }
        }

        // Guard casualties — same death/injury chance as player
        player.guards = player.guards || [];
        if (player.guards.length > 0) {
            result.guardCasualties = [];
            var deathChanceGuard = isWartime ? 0.05 : 0.02;
            var injuryChanceGuard = won ? 0.15 : 0.50;
            if (isSea && !won) injuryChanceGuard = 0.60;
            for (var _gi = player.guards.length - 1; _gi >= 0; _gi--) {
                var _guard = player.guards[_gi];
                var guardNpc = (_guard.personId && Engine.getPerson) ? Engine.getPerson(_guard.personId) : null;
                if (!won && rng.chance(deathChanceGuard)) {
                    // Guard killed
                    if (guardNpc) { guardNpc.alive = false; guardNpc.deathDay = Engine.getDay(); guardNpc.deathCause = 'combat'; guardNpc.isPlayerGuard = false; }
                    result.guardCasualties.push({ name: _guard.name, outcome: 'killed' });
                    Engine.logEvent('💀 Your guard ' + _guard.name + ' was killed by ' + enemyName + '!');
                    player.guards.splice(_gi, 1);
                } else if (rng.chance(injuryChanceGuard)) {
                    // Guard injured
                    var gSeverity = rng.chance(0.4) ? 'severe' : 'moderate';
                    if (guardNpc) { guardNpc.injured = true; guardNpc.injurySeverity = gSeverity; }
                    result.guardCasualties.push({ name: _guard.name, outcome: 'injured', severity: gSeverity });
                    Engine.logEvent('🩹 Your guard ' + _guard.name + ' suffered a ' + gSeverity + ' injury in the fight.');
                }
            }
            player.personalGuards = player.guards.length;
        }

        // Family companion casualties — same odds as player
        if (player.travelCompanions && player.travelCompanions.length > 0) {
            result.familyCasualties = [];
            var _fcDeathChance = isWartime ? 0.05 : 0.02;
            var _fcInjuryChance = won ? 0.15 : 0.50;
            if (isSea && !won) _fcInjuryChance = 0.60;
            for (var _fci2 = player.travelCompanions.length - 1; _fci2 >= 0; _fci2--) {
                var _comp = player.travelCompanions[_fci2];
                var _compNpc = Engine.findPerson(_comp.npcId);
                if (!_compNpc || !_compNpc.alive) continue;
                // Check if companion has armor/weapon (reduces death chance)
                var compHasArmor = _compNpc.armor;
                var compHasWeapon = _compNpc.weapon;
                var compDeathChance = _fcDeathChance;
                if (compHasArmor) compDeathChance *= 0.5;
                if (compHasWeapon) compDeathChance *= 0.7;
                if (!won && rng.chance(compDeathChance)) {
                    _compNpc.alive = false;
                    _compNpc.deathDay = Engine.getDay();
                    _compNpc.deathCause = 'Killed by ' + enemyName;
                    _compNpc.causeOfDeath = 'killed by ' + enemyName;
                    result.familyCasualties.push({ name: _comp.name, role: _comp.role, outcome: 'killed' });
                    Engine.logEvent('💀 Your ' + _comp.role + ' ' + _comp.name + ' was killed by ' + enemyName + '!');
                    // Remove from familyMembers
                    for (var _fmr = 0; _fmr < player.familyMembers.length; _fmr++) {
                        if (player.familyMembers[_fmr].npcId === _comp.npcId) {
                            player.familyMembers.splice(_fmr, 1);
                            break;
                        }
                    }
                    player.travelCompanions.splice(_fci2, 1);
                } else if (rng.chance(_fcInjuryChance)) {
                    var fcSeverity = rng.chance(0.4) ? 'severe' : 'moderate';
                    _compNpc.injured = true;
                    _compNpc.injurySeverity = fcSeverity;
                    result.familyCasualties.push({ name: _comp.name, role: _comp.role, outcome: 'injured', severity: fcSeverity });
                    Engine.logEvent('🩹 Your ' + _comp.role + ' ' + _comp.name + ' suffered a ' + fcSeverity + ' injury in the fight.');
                }
            }
        }

        return result;
    }

    function getEncounterRiskLabel() {
        if (!player.traveling) return null;
        var info = getEncounterChance();
        if (info.chance <= 0) return null;
        var label, color, icon;
        if (info.riskLevel === 'high') {
            label = 'High'; color = '#e74c3c'; icon = '🔴';
        } else if (info.riskLevel === 'medium') {
            label = 'Medium'; color = '#f39c12'; icon = '🟡';
        } else {
            label = 'Low'; color = '#2ecc71'; icon = '🟢';
        }
        var typeLabel = info.isSea ? (info.isWartime ? 'Navy' : 'Pirate') : (info.isWartime ? 'Ambush' : 'Bandit');
        return { label: label, color: color, icon: icon, typeLabel: typeLabel, chance: info.chance };
    }

    function checkWartimeAmbush(route) {
        if (!route || route.length === 0) return null;
        var rng = Engine.getRng();
        if (!rng) return null;

        // Check if any route segment is in a warzone
        var inWarzone = false;
        var activeWars = Engine.getActiveWars ? Engine.getActiveWars() : {};
        if (!activeWars || Object.keys(activeWars).length === 0) return null;

        for (var i = 0; i < route.length; i++) {
            var seg = route[i];
            var fromTown = Engine.findTown(seg.fromTownId);
            var toTown = Engine.findTown(seg.toTownId);
            if (!fromTown || !toTown) continue;
            // Check if these towns belong to warring kingdoms
            for (var warId in activeWars) {
                var war = activeWars[warId];
                if (!war) continue;
                var sides = war.sides || [war.attackerId, war.defenderId];
                if (sides.length < 2) continue;
                var fromSide = sides.indexOf(fromTown.kingdomId);
                var toSide = sides.indexOf(toTown.kingdomId);
                if (fromSide >= 0 && toSide >= 0 && fromSide !== toSide) { inWarzone = true; break; }
                // Check if near frontline
                if (fromSide >= 0 || toSide >= 0) {
                    var frontlineTowns = getFrontlineTowns(sides);
                    if (frontlineTowns.has(fromTown.id) || frontlineTowns.has(toTown.id)) { inWarzone = true; break; }
                }
            }
            if (inWarzone) break;
        }

        if (!inWarzone) return null;

        var chance = CONFIG.WARTIME_AMBUSH_BASE_CHANCE;

        // Military goods bonus
        var milGoods = ['swords', 'armor', 'bows', 'arrows', 'horses'];
        var carryingMilitary = milGoods.some(g => (player.inventory[g] || 0) > 0);
        if (carryingMilitary) chance += CONFIG.WARTIME_AMBUSH_MILITARY_GOODS_BONUS;

        // Enemy citizen bonus
        for (var wid in activeWars) {
            var w = activeWars[wid];
            var wSides = w.sides || [w.attackerId, w.defenderId];
            for (var s = 0; s < wSides.length; s++) {
                if (wSides[s] !== player.citizenshipKingdomId) {
                    var enemySide = wSides[s];
                    var routeTowns = route.map(r => Engine.findTown(r.toTownId)).filter(Boolean);
                    if (routeTowns.some(t => t.kingdomId === enemySide)) {
                        chance += CONFIG.WARTIME_AMBUSH_ENEMY_CITIZEN_BONUS;
                        break;
                    }
                }
            }
        }

        // Mitigations
        if (player.armedEscort && player.armedEscort.active) chance -= CONFIG.WARTIME_ESCORT_REDUCTION;
        if (hasSkill('combat_trained')) chance -= 0.10;
        if (hasSkill('battle_hardened')) chance -= 0.15;
        if (hasSkill('fortified_caravans')) chance -= 0.10;
        if (player.weapon) chance -= (typeof player.weapon === 'object') ? (player.weapon.combatBonus * 0.25) : 0.05;
        if (player.armor) chance -= (typeof player.armor === 'object') ? (player.armor.combatBonus * 0.17) : 0.05;
        var rankIdx = getPlayerRankIndex();
        if (rankIdx >= 4) chance -= 0.05; // Minor Noble+

        chance = Math.max(0.02, chance);

        if (!rng.chance(chance)) return null;

        // Ambushed!
        var inventoryLoss = {};
        var invKeys = Object.keys(player.inventory).filter(k => player.inventory[k] > 0);
        var lossPct = 0.2 + rng.random() * 0.3; // 20-50%
        for (var k = 0; k < invKeys.length; k++) {
            var key = invKeys[k];
            var loseQty = Math.floor(player.inventory[key] * lossPct);
            if (loseQty > 0) {
                player.inventory[key] -= loseQty;
                if (player.inventory[key] <= 0) delete player.inventory[key];
                inventoryLoss[key] = loseQty;
            }
        }

        var goldLossPct = 0.1 + rng.random() * 0.2; // 10-30%
        var goldLost = Math.floor(player.gold * goldLossPct);
        player.gold -= goldLost;

        var injured = rng.chance(0.15);
        if (injured) {
            player.injuries = player.injuries || [];
            player.injuries.push({ type: 'ambush_wound', severity: 'moderate', dayOccurred: Engine.getDay(), treated: false });
            Player._applyConditionHealthHit('moderate');
        }

        var deathChance = 0.03;
        if (player.weapon) deathChance -= (typeof player.weapon === 'object') ? (player.weapon.combatBonus * 0.05) : 0.01;
        if (player.armor) deathChance -= (typeof player.armor === 'object') ? (player.armor.combatBonus * 0.05) : 0.01;
        if (hasSkill('combat_trained')) deathChance -= 0.005;
        var died = rng.chance(Math.max(0.001, deathChance));

        Engine.logEvent('⚔️ ' + player.fullName + ' was ambushed by enemy soldiers! Lost ' + goldLost + 'g and ' + Object.keys(inventoryLoss).length + ' types of goods.' + (injured ? ' Suffered injuries.' : '') + (died ? ' KILLED IN AMBUSH!' : ''));

        return { ambushed: true, goldLost: goldLost, inventoryLoss: inventoryLoss, injured: injured, died: died };
    }

    function getFrontlineTowns(sides) {
        var frontline = new Set();
        if (!sides || sides.length < 2) return frontline;
        var allTowns = Engine.getTowns ? Engine.getTowns() : [];
        var side0Towns = allTowns.filter(t => t.kingdomId === sides[0]);
        var side1Towns = allTowns.filter(t => t.kingdomId === sides[1]);
        for (var i = 0; i < side0Towns.length; i++) {
            for (var j = 0; j < side1Towns.length; j++) {
                var dist = Math.hypot((side0Towns[i].x || 0) - (side1Towns[j].x || 0), (side0Towns[i].y || 0) - (side1Towns[j].y || 0));
                if (dist < CONFIG.WARTIME_FRONTLINE_DISTANCE) {
                    frontline.add(side0Towns[i].id);
                    frontline.add(side1Towns[j].id);
                }
            }
        }
        return frontline;
    }

    // ========================================================
    // §12L  ORDER PERMIT BONUSES
    // ========================================================
    function getOrderCompletionBonus(order) {
        if (!order) return 0;
        var totalValue = (order.qty || 0) * (order.assignedPrice || order.maxPricePerUnit || 0);
        var bonusPct = 0.10 + Math.random() * 0.10; // 10-20%
        return Math.floor(totalValue * bonusPct);
    }

    function canBidOnBannedOrder(kingdomId, resourceId) {
        var permits = player.productionPermits || {};
        var kingdomPermits = permits[kingdomId] || [];
        return kingdomPermits.includes(resourceId);
    }


