        // Utility
        getInventoryValue() {
            var carried = Object.entries(player.inventory).reduce((sum, [resId, qty]) => {
                const res = findResource(resId);
                return sum + (res ? res.basePrice * qty : 0);
            }, 0);
            var stored = 0;
            for (var tid in player.townStorage) {
                for (var resId in player.townStorage[tid]) {
                    if (resId.charAt(0) === '_') continue;
                    var qty = player.townStorage[tid][resId] || 0;
                    if (typeof qty !== 'number' || qty <= 0) continue;
                    var res = findResource(resId);
                    stored += (res ? res.basePrice * qty : 0);
                }
            }
            return carried + stored;
        },

        getNetWorth() {
            let worth = player.gold + Player.getInventoryValue();
            for (const bld of player.buildings) {
                const bt = Engine.findBuildingType(bld.type);
                if (bt) worth += bt.cost * bld.level * 0.5;
            }
            for (const ship of player.ships) {
                const st = CONFIG.SHIP_TYPES[ship.type];
                if (st) worth += (st.laborCost || 0) * (ship.condition / 100) * 0.7;
            }
            return Math.floor(worth);
        },

        // Portrait system
        getPersonPortrait: getPersonPortrait,
        generatePortrait: generatePortrait,
        generateRandomPortrait: generateRandomPortrait,
